#!/usr/bin/env python3
import sys
import json
import time
import urllib.request
import urllib.error

API_URL = "http://127.0.0.1:4000/v1/chat/completions"
TEST_PROMPT = "Reply with exactly one word: OK"
TIMEOUT = 30  # seconds
MAX_RESPONSE_PREVIEW = 50


def load_models(path):
    with open(path, "r", encoding="utf-8") as f:
        data = json.load(f)

    # Expect either:
    #   ["model-a", "model-b", ...]
    # or {"models": ["model-a", "model-b", ...]}
    if isinstance(data, list):
        return [str(m) for m in data]
    if isinstance(data, dict) and isinstance(data.get("models"), list):
        return [str(m) for m in data["models"]]

    raise ValueError("JSON must be a list of model names or an object with a 'models' list.")


def extract_response_text(raw_body):
    try:
        obj = json.loads(raw_body)
    except Exception:
        return raw_body.strip()

    choices = obj.get("choices", [])
    if choices:
        first = choices[0]
        if isinstance(first, dict):
            # OpenAI-compatible chat style
            msg = first.get("message")
            if isinstance(msg, dict):
                content = msg.get("content")
                if isinstance(content, str):
                    return content.strip()
            # Fallback: completion-style "text"
            if "text" in first:
                return str(first["text"]).strip()

    return raw_body.strip()


def send_request(model, include_temperature=True):
    payload = {
        "model": model,
        "messages": [{"role": "user", "content": TEST_PROMPT}],
        "max_tokens": 20,
    }
    if include_temperature:
        payload["temperature"] = 0

    data = json.dumps(payload).encode("utf-8")
    req = urllib.request.Request(
        API_URL,
        data=data,
        headers={"Content-Type": "application/json"},
        method="POST",
    )

    with urllib.request.urlopen(req, timeout=TIMEOUT) as resp:
        body = resp.read().decode("utf-8", errors="replace")
    return body


def call_model(model):
    start = time.time()
    error_msg = None

    # First try with temperature
    try:
        body = send_request(model, include_temperature=True)
        latency = time.time() - start
        text = extract_response_text(body)
        return True, latency, text
    except urllib.error.HTTPError as e:
        body = e.read().decode("utf-8", errors="ignore")
        lower = body.lower()

        # Detect "temperature not supported" style errors and retry without it
        if (
            "temperature" in lower
            and ("unsupported" in lower or "unknown" in lower or "unexpected" in lower or "extra field" in lower)
        ):
            try:
                body2 = send_request(model, include_temperature=False)
                latency = time.time() - start
                text = extract_response_text(body2)
                return True, latency, text
            except Exception as e2:
                latency = time.time() - start
                error_msg = f"Retry failed: {e2}"
        else:
            latency = time.time() - start
            error_msg = f"HTTP {e.code}: {body.strip()[:MAX_RESPONSE_PREVIEW]}"
    except urllib.error.URLError as e:
        latency = time.time() - start
        error_msg = f"URLError: {e.reason}"
    except Exception as e:
        latency = time.time() - start
        error_msg = f"Error: {e}"

    return False, latency, error_msg or "Unknown error"


def main():
    if len(sys.argv) != 2:
        print(f"Usage: {sys.argv[0]} MODELS_JSON")
        sys.exit(1)

    try:
        models = load_models(sys.argv[1])
    except Exception as e:
        print(f"Failed to load models: {e}")
        sys.exit(1)

    results = []
    ok_count = 0
    fail_count = 0

    for model in models:
        success, latency, resp = call_model(model)

        # Determine pass/fail by response content if request succeeded
        if success:
            # Normalize whitespace for checking
            normalized = " ".join(resp.split())
            passed = normalized == "OK"
        else:
            passed = False

        status = "✅" if passed else "❌"
        if passed:
            ok_count += 1
        else:
            fail_count += 1

        latency_str = f"{latency:.3f}s"
        preview = (resp or "").replace("\n", " ")[:MAX_RESPONSE_PREVIEW]

        results.append((model, status, latency_str, preview))

    # Compute column widths
    headers = ["Model", "Status", "Latency", "Response"]
    cols = list(zip(*([headers] + results)))
    widths = [max(len(str(item)) for item in col) for col in cols]

    def fmt_row(row):
        return " | ".join(str(cell).ljust(width) for cell, width in zip(row, widths))

    # Print table
    print(fmt_row(headers))
    print("-+-".join("-" * w for w in widths))
    for row in results:
        print(fmt_row(row))

    total = len(models)
    print(f"\nTotal: {total} models | ✅ {ok_count} working | ❌ {fail_count} failed")


if __name__ == "__main__":
    main()
